10	// These tests protect the recovery workflow documented in the README: a write
11	// failure can strike in the middle of persisting a multi-node batch, leaving
12	// some nodes' new records durably saved and others not yet saved. The command
13	// must report the failure with new=0 duplicate=0 (it must not present the
14	// already-persisted part as a successful batch), and resubmitting the very
15	// same JSON verbatim after the fault is cleared must converge: saved records
16	// count as duplicates, the one record still missing is added exactly once,
17	// and the batch-internal repeat still counts as a duplicate.
18	//
19	// The fault is injected only at the persistence boundary (writeNodeFile),
20	// after all validation and merging has run, so the exercise goes through the
21	// real code path — real atomic file writes, real on-disk state afterwards —
22	// without filling a disk or relying on wall-clock timing. The same two nodes
23	// run under both failure positions, so the result cannot depend on which node
24	// happens to be written first (that order is deliberately not promised).
25	
26	// persistFault temporarily replaces writeNodeFile. failOnCall is the
27	// 1-based number of the node-file write that must return an error; every
28	// other write performs the real atomic persistence. It returns a pointer to
29	// the number of writes actually attempted.
30	func persistFault(t *testing.T, failOnCall int) *int {
31		t.Helper()
32		calls := 0
33		orig := writeNodeFile
34		writeNodeFile = func(path string, records []Heartbeat) error {
35			calls++
36			if calls == failOnCall {
37				return errors.New("injected persistence failure")
38			}
39			return orig(path, records)
40		}
