94		// with identical content, and one existing seq 1 is carried along: four
95		// input records in total, all legal.
96		alpha2 := hb("alpha", 2, receive.Add(-time.Minute), "1.0", 101, 0)
97		beta2 := hb("beta", 2, receive.Add(-time.Minute), "1.0", 201, 1)
98		batch := []Heartbeat{alpha2, alpha2, beta2, beta1}
99	
100		// Fail the SECOND node-file write. Both nodes gain a record, so exactly
101		// one real write completes and durably renames a file into place before
102		// the failing one: this is a genuine partial save, not an error returned
103		// before anything was persisted.
104		calls := persistFault(t, 2)
