108		}
109		if !strings.Contains(err.Error(), "failed to persist heartbeat batch") {
110			t.Fatalf("error must be the persistence failure, got: %v", err)
111		}
112		if newC != 0 || dupC != 0 {
113			t.Errorf("failed submit must report new=0 duplicate=0, got new=%d duplicate=%d (the already-saved part must not be reported as success)", newC, dupC)
114		}
115		if *calls != 2 {
116			t.Fatalf("test setup: expected two node-file writes (one success, one failure), got %d; a failure that saved no new record is a different scenario", *calls)
