1	package edgefleet
2	
3	import (
4		"crypto/sha256"
5		"encoding/hex"
6		"encoding/json"
7		"fmt"
8		"os"
9		"path/filepath"
10		"strings"
11		"testing"
12		"time"
13	)
14	
15	// These tests protect storage and querying of long node ids. A node id is
16	// arbitrary legal Unicode text of any length: the old per-node hex file name
17	// doubles the id's byte length, so 126 ASCII characters (or 42 Han characters)
18	// already exceed a 255-byte local file-name limit and made submit fail and
19	// queries for the unsaved node look like read failures. Long ids now use a
20	// fixed-length, content-addressed slot file; node identity nevertheless stays
21	// the user's full text, with the same ownership, dedup and conflict rules.
22	
23	// slotPath mirrors the store's long-id slot naming.
24	func slotPath(store *Store, nodeID string) string {
25		sum := sha256.Sum256([]byte(nodeID))
26		return filepath.Join(store.slotsDir, hex.EncodeToString(sum[:])+".json")
27	}
28	
29	// isLongID reports whether the id uses a slot rather than a legacy hex name.
30	func isLongID(nodeID string) bool {
31		return len(hex.EncodeToString([]byte(nodeID))+".json") > maxNodeFileNameBytes
32	}
33	
34	func TestLongNodeIDStorageLayout(t *testing.T) {
35		store, err := OpenStore(t.TempDir())
36		if err != nil {
37			t.Fatal(err)
38		}
39		short := "n1"
40		shortLoc := store.nodeLocationFor(short)
41		if filepath.Dir(shortLoc.path) != store.nodesDir {
42			t.Fatalf("short id must stay under nodes/, got %s", shortLoc.path)
43		}
44		if filepath.Base(shortLoc.path) != hex.EncodeToString([]byte(short))+".json" {
45			t.Fatalf("short id file name changed: %s", shortLoc.path)
46		}
47	
48		// Boundary ids: 125 id bytes -> a 255-byte hex name (still legacy, exactly
49		// the largest name the old code could ever have written); 126 id bytes ->
50		// 257 bytes (would fail) -> a fixed-length slot.
51		boundaryLegacy := strings.Repeat("a", 125)
52		boundarySlot := strings.Repeat("a", 126)
53		if isLongID(boundaryLegacy) {
54			t.Fatal("125-byte id has a 255-byte name and must keep its legacy path")
55		}
56		if !isLongID(boundarySlot) {
57			t.Fatal("126-byte id must use a slot")
58		}
59		legacyLoc := store.nodeLocationFor(boundaryLegacy)
60		if filepath.Dir(legacyLoc.path) != store.nodesDir ||
61			filepath.Base(legacyLoc.path) != hex.EncodeToString([]byte(boundaryLegacy))+".json" {
62			t.Fatalf("boundary legacy id moved: %s", legacyLoc.path)
63		}
64	
65		for _, id := range []string{boundarySlot, strings.Repeat("汉", 42), strings.Repeat("x", 4096)} {
66			loc := store.nodeLocationFor(id)
67			if filepath.Dir(loc.path) != store.slotsDir {
68				t.Fatalf("long id (bytes=%d) must live under slots/, got %s", len(id), loc.path)
69			}
70			base := filepath.Base(loc.path)
71			if len(base) != 64+len(".json") {
72				t.Errorf("slot name %q is not the fixed 64-hex-char length", base)
73			}
74			if base != filepath.Base(slotPath(store, id)) {
75				t.Errorf("slot name mismatch for id bytes=%d", len(id))
76			}
77			if loc.path == store.nodeLocationFor(id+"x").path {
78				t.Errorf("id and id+%q share a slot: storage merges distinct nodes", "x")
79			}
80		}
81		for _, id := range []string{boundarySlot, strings.Repeat("汉", 42)} {
82			// The slot name is opaque hex and cannot embed the id text; a long run
83			// of the id's characters must not appear in a 64-hex-char hash name
84			// (hanzi cannot occur in hex at all; ten repeated hex chars by chance
85			// is negligible).
86			base := filepath.Base(store.nodePath(id))
87			r := []rune(id)[0]
88			var marker string
89			if r < 128 {
90				marker = strings.Repeat(string(r), 10)
91			} else {
92				marker = string(r)
93			}
94			if strings.Contains(base, marker) {
95				t.Errorf("slot name %q appears to embed id text", base)
96			}
97		}
98	}
