100	func TestLongNodeIDsSaveAndQuery(t *testing.T) {
101		dir := t.TempDir()
102		store, err := OpenStore(dir)
103		if err != nil {
104			t.Fatal(err)
105		}
106		receive := testBase
107	
108		cases := []struct {
109			name string
110			id   string
111		}{
112			{"126 ascii", strings.Repeat("a", 126)},
113			{"127 ascii", strings.Repeat("b", 127)},
114			{"42 hanzi", strings.Repeat("汉", 42)},
115			{"hanzi and emoji", strings.Repeat("节", 41) + "😀"},
116			{"spaces hanzi emoji", strings.Repeat(" ", 61) + strings.Repeat("汉", 22) + "😀"},
117			{"very long ascii", strings.Repeat("edge-", 200)},
118		}
119		for i, tc := range cases {
120			t.Run(tc.name, func(t *testing.T) {
121				if !isLongID(tc.id) {
122					t.Fatalf("test id (%d bytes) is not a long id", len(tc.id))
123				}
124				r := hb(tc.id, 1, receive.Add(-time.Second), "v"+tc.name, int64(100+i), int64(i))
125				newC, dupC, err := store.Submit([]Heartbeat{r}, receive)
126				if err != nil {
127					t.Fatalf("long id submit failed: %v", err)
128				}
129				if newC != 1 || dupC != 0 {
130					t.Fatalf("new=%d dup=%d, want 1/0", newC, dupC)
131				}
132				// The record is in a slot whose name is short enough for any local
133				// file system, and no over-long legacy name was created.
134				info, err := os.Stat(store.nodePath(tc.id))
135				if err != nil {
136					t.Fatalf("slot not written: %v", err)
137				}
138				if len(info.Name()) > 255 {
139					t.Errorf("slot name length %d still exceeds 255", len(info.Name()))
140				}
141				legacyEntries, err := os.ReadDir(store.nodesDir)
142				if err != nil {
143					t.Fatal(err)
144				}
145				for _, e := range legacyEntries {
146					if len(e.Name()) > maxNodeFileNameBytes {
147						t.Errorf("long id must not create an over-long nodes/ name: %d-byte name", len(e.Name()))
148					}
149				}
150	
151				// Health reads this node's own telemetry, selected by greatest seq.
152				got, err := store.Health(tc.id, receive, "v"+tc.name, 99)
153				if err != nil {
154					t.Fatalf("health failed: %v", err)
155				}
156				if got.NodeID != tc.id || got.Status != "online" || got.Seq != 1 ||
157					got.Version != "v"+tc.name || got.Height != int64(100+i) || got.Missed != int64(i) {
158					t.Errorf("health misread the node or its telemetry: %+v", got)
159				}
160	
161				// History round-trips the full id and record.
162				hist, err := store.History(tc.id)
163				if err != nil || len(hist) != 1 || !hist[0].Equal(r) {
164					t.Fatalf("history broken: %+v err=%v", hist, err)
165				}
166			})
167		}
168	
169		// A fresh store instance on the same directory sees the same data.
170		reopened, err := OpenStore(dir)
171		if err != nil {
172			t.Fatal(err)
173		}
174		got, err := reopened.Health(cases[1].id, receive, "v127 ascii", 99)
175		if err != nil || got.Height != 101 {
176			t.Fatalf("long id data not readable after restart: %+v err=%v", got, err)
177		}
178	}
