404		// Case 1: another long node's complete, valid file is planted at idA's
405		// slot. Format and checksum are intact; the records name idB.
406		slotA := store.nodePath(idA)
407		copyFileBytes(t, store, idA, idB)
408	
409		check := func(name string, err error) {
410			t.Helper()
411			if err == nil || !IsCorrupt(err) {
412				t.Fatalf("%s must refuse the foreign slot file as corruption, got %v", name, err)
413			}
414			msg := err.Error()
415			for _, want := range []string{slotA, "record 1", fmt.Sprintf("%q", idA), fmt.Sprintf("%q", idB)} {
416				if !strings.Contains(msg, want) {
