430			t.Errorf("foreign file must not read as no telemetry")
431		}
432	
433		// A continued submit touching idA fails the whole batch atomically and
434		// must not overwrite, delete or replace the planted file; idB and the
435		// short nodes are unaffected.
436		planted, err := os.ReadFile(slotA)
437		if err != nil {
438			t.Fatal(err)
439		}
440		newC, dupC, err := store.Submit([]Heartbeat{
441			hb(idA, 9, receive.Add(-time.Second), "1.0", 999, 0),
442			hb(shortD, 2, receive.Add(-time.Second), "1.0", 401, 0),
443			hb("fresh-node", 1, receive.Add(-time.Second), "1.0", 1, 0),
444		}, receive)
445		if err == nil || !IsCorrupt(err) {
446			t.Fatalf("submit must refuse a batch touching the misowned slot, got %v", err)
447		}
448		if newC != 0 || dupC != 0 {
449			t.Errorf("rejected batch must report no counts, got new=%d dup=%d", newC, dupC)
450		}
451		after, err := os.ReadFile(slotA)
452		if err != nil || string(after) != string(planted) {
453			t.Errorf("the refused submit must not modify the misowned slot")
454		}
455		if r, err := store.Health(idB, receive, "1.0", 99); err != nil || r.Height != 200 || r.Missed != 7 {
456			t.Errorf("the copied-from long node must stay queryable: %+v err=%v", r, err)
457		}
458		if r, err := store.Health(shortD, receive, "1.0", 0); err != nil || r.Seq != 1 {
459			t.Errorf("short node in the rejected batch must be unchanged: %+v err=%v", r, err)
460		}
461	
462		// Case 2: a short node's valid file planted in a long node's slot is
463		// refused by the record-vs-queried-id ownership check.
464		copyFileBytes(t, store, idA, shortC)
465		if _, err := loadNodeFileFor(store, idA); err == nil || !IsCorrupt(err) {
466			t.Fatalf("short node file in long slot must be corrupt, got %v", err)
