1	package main
2	
3	// End-to-end command-line tests for long node ids. The package tests cover the
4	// store mapping and ownership rules; these tests exercise what a user actually
5	// does through the real command: submitting, querying health and history,
6	// seeing "no telemetry" for a never-saved long id, and getting an explicit
7	// corruption refusal when another node's file occupies the slot.
8	
9	import (
10		"os"
11		"path/filepath"
12		"strings"
13		"testing"
14	)
15	
16	// longIDJSON builds one heartbeat object for the given long node.
17	func longIDJSON(node string, seq, height, missed int, version, collected string) string {
18		return `[{"node":` + quoteJSON(node) + `,"seq":` + itoa(seq) +
19			`,"collected_at":"` + collected + `","version":"` + version +
20			`","height":` + itoa(height) + `,"missed":` + itoa(missed) + `}]`
21	}
22	
23	func quoteJSON(s string) string {
24		b := strings.Builder{}
25		b.WriteByte('"')
26		for _, r := range s {
27			switch r {
28			case '"':
29				b.WriteString(`\"`)
30			case '\\':
31				b.WriteString(`\\`)
32			default:
33				b.WriteRune(r)
34			}
35		}
36		b.WriteByte('"')
37		return b.String()
38	}
39	
40	func itoa(n int) string {
41		if n == 0 {
42			return "0"
43		}
44		var buf [24]byte
45		i := len(buf)
46		neg := n < 0
47		if neg {
48			n = -n
49		}
50		for n > 0 {
51			i--
52			buf[i] = byte('0' + n%10)
53			n /= 10
54		}
55		if neg {
56			i--
57			buf[i] = '-'
58		}
59		return string(buf[i:])
60	}
61	
62	func TestCLILongNodeIDSubmitHealthHistory(t *testing.T) {
63		dir := t.TempDir()
64		collected := "2026-10-01T11:59:59Z"
65	
66		cases := []struct {
67			name string
68			node string
69		}{
70			{"126 ascii", strings.Repeat("a", 126)},
71			{"127 ascii", strings.Repeat("b", 127)},
72			{"42 hanzi", strings.Repeat("汉", 42)},
73			{"hanzi emoji spaces", strings.Repeat("节", 40) + "😀 " + strings.Repeat("x", 5)},
74		}
75		for _, tc := range cases {
